import { slimTokens } from "../../catalog/index.js";
export const taskStatusTag = { closed: "CLOSED" };
export function task(opts) {
    if (opts.name.trim() === "")
        throw new Error("task requires a non-empty name.");
    if (opts.handle !== undefined && !/^[A-Za-z]+$/.test(opts.handle))
        throw new Error(`task ${JSON.stringify(opts.name)}: handle must contain only letters.`);
    if (opts.namespace !== undefined && !/^[A-Za-z]+$/.test(opts.namespace))
        throw new Error(`task ${JSON.stringify(opts.name)}: namespace must contain only letters.`);
    if (opts.category.refName.trim() === "")
        throw new Error(`task ${JSON.stringify(opts.name)}: category ref is required.`);
    return { def(refName) {
            const handle = opts.handle ?? refName.replace(/[^A-Za-z]/g, "").toUpperCase();
            const namespace = opts.namespace ?? refName.replace(/[^A-Za-z]/g, "").toLowerCase();
            return { kind: "task", parent: "org", refName, payload: slimTokens({ ...opts, handle, namespace }), ...(opts.enabled !== undefined ? { enabled: opts.enabled } : {}) };
        } };
}
